#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
namespace FileCompass {internal static class SearchMediaUxTests {
 internal static int Run(string root){Directory.CreateDirectory(root);var checks=new List<string>();Window current=null;string motif=AppearanceTheme.Motif;Action<bool,string> check=(yes,text)=>{if(!yes)throw new Exception(text);checks.Add(text);};try{SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));L.ChangeLanguage("cs-CZ");FluentTheme.Ensure();AppearanceTheme.Apply("Light");foreach(string style in new[]{"Original","Balanced"}){AppearanceTheme.SetMotif(style);foreach(var size in new[]{new Size(880,720),new Size(1050,800)}){var search=new FileSearchWindow(null,root,true,true,delegate{return 0;},delegate{});current=search;Place(search);search.Width=size.Width;search.Height=size.Height;search.Show();search.UpdateLayout();var tabs=FluentUiTests.Children<TabControl>(search).Single();for(int i=0;i<4;i++){tabs.SelectedIndex=i;search.UpdateLayout();NavigationTests.Wait(Task.Delay(60));check(!FluentUiTests.Children<ScrollViewer>(tabs).Any(x=>x.ComputedVerticalScrollBarVisibility==Visibility.Visible),style+size.Width+" search page "+i+": no form scrollbar");check(FluentUiTests.Children<ListView>(search).Single().ActualHeight>=110,style+size.Width+" search page "+i+": results retain usable space");NextStageTests.Draw(search,Path.Combine(root,style+"-search-"+size.Width+"-"+i+".png"));}check(search.ReadSearchOptions().Mask=="*.*",style+": search defaults preserved");search.Close();current=null;}
 var media=new MediaConverterWindow(null,new string[0],root,true,delegate{},delegate{});current=media;Place(media);media.Show();NavigationTests.Wait(media.AnalysisTask);
File.WriteAllLines(Path.Combine(root,style+"-tab-diagnostics.txt"),FluentUiTests.Children<TabControl>(media).SelectMany(c=>c.Items.Cast<TabItem>()).Select(t=>Convert.ToString(t.Header)+" template="+(t.Template.FindName("TabFrame",t)!=null)+" height="+t.ActualHeight+" style="+DependencyPropertyHelper.GetValueSource(t,FrameworkElement.StyleProperty).BaseValueSource));
foreach(int mode in new[]{0,1})foreach(int page in new[]{0,1}){media.Mode.SelectedIndex=mode;media.SettingsTabs.SelectedIndex=page;media.UpdateLayout();check(FluentUiTests.Children<TextBlock>(media).Any(x=>x.FontSize==20&&x.Text==L.Text("media.title")),style+mode+page+": converter clean header");NextStageTests.Draw(media,Path.Combine(root,style+"-media-"+mode+"-"+page+".png"));}media.Close();current=null;
 var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(80)};Exception issue=null;timer.Tick+=delegate{var dialog=Application.Current.Windows.Cast<Window>().FirstOrDefault(x=>x.IsVisible&&x.Title==L.Text("tags.results"));if(dialog==null)return;timer.Stop();try{check(FluentUiTests.Children<TextBlock>(dialog).Any(x=>x.Text.Contains(L.Text("tags.searchHelp"))),style+": tag search explains custom labels");check(dialog.ActualHeight<500,style+": tag search prompt has no blank oversized area");NextStageTests.Draw(dialog,Path.Combine(root,style+"-tags.png"));}catch(Exception ex){issue=ex;}dialog.DialogResult=false;};timer.Start();try{check(SettingsUx.Prompt(null,L.Text("tags.results"),"",L.Text("tags.searchHelp")+"\n\n"+L.Text("tags.globalPrompt"),"action.search")==null,style+": cancelling tag query returns no query");}finally{timer.Stop();}if(issue!=null)throw issue;
 }File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count+" checks"}));return 0;}catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"FAIL: "+ex}));return 1;}finally{if(current!=null)current.Close();AppearanceTheme.SetMotif(motif);}}
 static void Place(Window w){w.WindowStartupLocation=WindowStartupLocation.Manual;w.Left=-18000;w.Top=-18000;w.ShowActivated=false;w.ShowInTaskbar=false;}
}}
